PRAGMA foreign_keys=ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE obra(id TEXT PRIMARY KEY,autor TEXT NOT NULL,titulo TEXT NOT NULL,pais TEXT,genero TEXT,anio INTEGER,fuente TEXT NOT NULL,sha256 TEXT NOT NULL,caracteres INTEGER NOT NULL,particion TEXT NOT NULL CHECK(particion IN ('train','dev','test')),estado_bibliografico TEXT NOT NULL);
CREATE TABLE parrafo(id INTEGER PRIMARY KEY,obra_id TEXT NOT NULL REFERENCES obra(id),orden INTEGER NOT NULL,inicio INTEGER NOT NULL,fin INTEGER NOT NULL,texto TEXT NOT NULL,UNIQUE(obra_id,orden));
CREATE TABLE oracion(id INTEGER PRIMARY KEY,parrafo_id INTEGER NOT NULL REFERENCES parrafo(id),orden INTEGER NOT NULL,inicio INTEGER NOT NULL,fin INTEGER NOT NULL,texto TEXT NOT NULL,patron_pos TEXT NOT NULL,patron_dep TEXT NOT NULL,n_palabras INTEGER NOT NULL,UNIQUE(parrafo_id,orden));
CREATE TABLE forma(id INTEGER PRIMARY KEY,superficie TEXT UNIQUE NOT NULL,normalizada TEXT NOT NULL);
CREATE TABLE lema(id INTEGER PRIMARY KEY,lema TEXT NOT NULL,pos TEXT NOT NULL,UNIQUE(lema,pos));
CREATE TABLE morfologia(id INTEGER PRIMARY KEY,rasgos TEXT UNIQUE NOT NULL);
CREATE TABLE token(oracion_id INTEGER NOT NULL REFERENCES oracion(id),posicion INTEGER NOT NULL,forma_id INTEGER NOT NULL REFERENCES forma(id),lema_id INTEGER NOT NULL REFERENCES lema(id),morfologia_id INTEGER NOT NULL REFERENCES morfologia(id),tag TEXT NOT NULL,dep TEXT NOT NULL,cabeza INTEGER NOT NULL,inicio INTEGER NOT NULL,fin INTEGER NOT NULL,es_palabra INTEGER NOT NULL,espacio TEXT NOT NULL,PRIMARY KEY(oracion_id,posicion)) WITHOUT ROWID;
CREATE TABLE entidad(oracion_id INTEGER NOT NULL REFERENCES oracion(id),inicio INTEGER NOT NULL,fin INTEGER NOT NULL,tipo TEXT NOT NULL,texto TEXT NOT NULL,PRIMARY KEY(oracion_id,inicio,fin,tipo)) WITHOUT ROWID;
CREATE TABLE frecuencia_forma(forma_id INTEGER PRIMARY KEY REFERENCES forma(id),frecuencia INTEGER NOT NULL,obras INTEGER NOT NULL);
CREATE TABLE frecuencia_lema(lema_id INTEGER PRIMARY KEY REFERENCES lema(id),frecuencia INTEGER NOT NULL,obras INTEGER NOT NULL);
CREATE TABLE frecuencia_obra(obra_id TEXT NOT NULL REFERENCES obra(id),lema_id INTEGER NOT NULL REFERENCES lema(id),frecuencia INTEGER NOT NULL,PRIMARY KEY(obra_id,lema_id)) WITHOUT ROWID;
CREATE TABLE flexion(lema_id INTEGER NOT NULL REFERENCES lema(id),forma_id INTEGER NOT NULL REFERENCES forma(id),morfologia_id INTEGER NOT NULL REFERENCES morfologia(id),frecuencia INTEGER NOT NULL,PRIMARY KEY(lema_id,forma_id,morfologia_id)) WITHOUT ROWID;
CREATE TABLE ngrama(n INTEGER NOT NULL CHECK(n IN (2,3)),secuencia TEXT NOT NULL,frecuencia INTEGER NOT NULL,PRIMARY KEY(n,secuencia)) WITHOUT ROWID;
CREATE TABLE colocacion(lema_a INTEGER NOT NULL REFERENCES lema(id),lema_b INTEGER NOT NULL REFERENCES lema(id),frecuencia INTEGER NOT NULL,distancia_media REAL NOT NULL,PRIMARY KEY(lema_a,lema_b)) WITHOUT ROWID;
CREATE TABLE relacion(cabeza_lema INTEGER NOT NULL REFERENCES lema(id),dependiente_lema INTEGER NOT NULL REFERENCES lema(id),dep TEXT NOT NULL,frecuencia INTEGER NOT NULL,PRIMARY KEY(cabeza_lema,dependiente_lema,dep)) WITHOUT ROWID;
CREATE TABLE patron(tipo TEXT NOT NULL,secuencia TEXT NOT NULL,frecuencia INTEGER NOT NULL,ejemplo_oracion INTEGER REFERENCES oracion(id),PRIMARY KEY(tipo,secuencia)) WITHOUT ROWID;
CREATE TABLE construccion(tipo TEXT NOT NULL,oracion_id INTEGER NOT NULL REFERENCES oracion(id),token_inicio INTEGER NOT NULL,token_fin INTEGER NOT NULL,criterio TEXT NOT NULL,PRIMARY KEY(tipo,oracion_id,token_inicio,token_fin)) WITHOUT ROWID;
CREATE TABLE estilo_obra(obra_id TEXT PRIMARY KEY REFERENCES obra(id),palabras INTEGER NOT NULL,formas_distintas INTEGER NOT NULL,lemas_distintos INTEGER NOT NULL,oraciones INTEGER NOT NULL,media_palabras REAL NOT NULL,ttr REAL NOT NULL,comas INTEGER NOT NULL,puntos INTEGER NOT NULL,interrogaciones INTEGER NOT NULL,exclamaciones INTEGER NOT NULL,rayas INTEGER NOT NULL,proporcion_dialogo REAL NOT NULL);
CREATE TABLE cuarentena(obra_id TEXT PRIMARY KEY,motivo TEXT NOT NULL);
CREATE VIEW v_lexico AS SELECT f.superficie,f.normalizada,x.frecuencia,x.obras FROM forma f JOIN frecuencia_forma x ON x.forma_id=f.id;
CREATE VIEW v_lemas AS SELECT l.lema,l.pos,x.frecuencia,x.obras FROM lema l JOIN frecuencia_lema x ON x.lema_id=l.id;
CREATE VIEW v_verbos AS SELECT l.lema,f.superficie,m.rasgos,x.frecuencia FROM flexion x JOIN lema l ON l.id=x.lema_id JOIN forma f ON f.id=x.forma_id JOIN morfologia m ON m.id=x.morfologia_id WHERE l.pos IN ('VERB','AUX');
CREATE VIEW v_concordancias AS SELECT o.id obra_id,o.autor,o.titulo,s.id oracion_id,s.texto,t.posicion,f.superficie,l.lema,l.pos,m.rasgos,t.dep,t.cabeza,t.inicio,t.fin FROM token t JOIN oracion s ON s.id=t.oracion_id JOIN parrafo p ON p.id=s.parrafo_id JOIN obra o ON o.id=p.obra_id JOIN forma f ON f.id=t.forma_id JOIN lema l ON l.id=t.lema_id JOIN morfologia m ON m.id=t.morfologia_id;
CREATE VIEW v_colocaciones AS SELECT a.lema lema_a,b.lema lema_b,c.frecuencia,c.distancia_media FROM colocacion c JOIN lema a ON a.id=c.lema_a JOIN lema b ON b.id=c.lema_b;
CREATE VIEW v_sintaxis AS SELECT a.lema nucleo,b.lema dependiente,r.dep,r.frecuencia FROM relacion r JOIN lema a ON a.id=r.cabeza_lema JOIN lema b ON b.id=r.dependiente_lema;
